fn origin_rules(document: &CommittedDocument) -> Vec<u8> {
    let origin = url::Url::parse(&document.canonical_url)
        .expect("validated document")
        .origin()
        .ascii_serialization();
    let mut pattern = String::from("^");
    for ch in origin.chars() {
        if ".*+?()[]{}^$|\\".contains(ch) {
            pattern.push('\\');
        }
        pattern.push(ch);
    }
    pattern.push('/');
    serde_json::to_vec(&serde_json::json!([
        {"trigger":{"url-filter":".*","resource-type":["document"]},"action":{"type":"block"}},
        {"trigger":{"url-filter":pattern,"resource-type":["document"]},"action":{"type":"ignore-previous-rules"}}
    ])).expect("static filter schema")
}
        .collect()
}
fn approved_origin_allows(allowed: Option<&CanonicalOrigin>, document: &CommittedDocument) -> bool {
    allowed.is_none_or(|origin| origin == &document.origin)
}

#[test]
fn filter_fences_scheme_host_and_port_without_regex_injection() {
    let document = CommittedDocument::parse("http://127.0.0.1:3456/page").unwrap();
    let rules: serde_json::Value = serde_json::from_slice(&origin_rules(&document)).unwrap();
    assert_eq!(rules[0]["action"]["type"], "block");
    assert_eq!(
        rules[1]["trigger"]["url-filter"],
        "^http://127\\.0\\.0\\.1:3456/"
    );
    assert_eq!(profile_key(StoragePartition::AgentTask(4)), "task-4");
    assert_ne!(
        profile_key(StoragePartition::Manual),
        profile_key(StoragePartition::Authentication(4))
    );
}
